{"edits":[{"path":"ops/build-runner/worker.mjs","old":"    const reviewerHelper = { id: 'reviewer', name: 'Internal Reviewer', description: 'Reviews and proves the build.', instructions: 'Review and prove the build changes; report any errors.', defaultModelId: coderModel, maxSteps: 12 }","new":"    const reviewerHelper = { id: 'reviewer', name: 'Internal Reviewer', description: 'Reviews and proves the build.', instructions: `Review and prove the build changes. Check actual changed files against the saved card acceptance criteria using workspace tools. Run actual file/command checks for content. The host owns the Git commit/clean-candidate check after model work, so do not retry Git administrative-path permission failures. Return the final literal REVIEW_AND_PROOF_PASSED only if all actual checks pass; otherwise return REVIEW_AND_PROOF_FAILED with reason.\n\nAuthoritative saved description:\n${description}`, defaultModelId: coderModel, maxSteps: 12 }"},{"path":"ops/build-runner/worker.mjs","old":"    if (!reviewerEnd || reviewerEnd.isError || !reviewerEnd.result) throw new Error('reviewer failed')","new":"    if (!reviewerEnd || reviewerEnd.isError || !reviewerEnd.result) throw new Error('reviewer failed')
    if (!String(reviewerEnd.result ?? '').includes('REVIEW_AND_PROOF_PASSED')) throw new Error('reviewer failed')
    if (String(reviewerEnd.result ?? '').includes('REVIEW_AND_PROOF_FAILED')) throw new Error('reviewer failed')
    if (!events.some(e => e?.type === 'subagent_tool_end' && e?.agentType === 'reviewer' && e?.isError === false)) throw new Error('reviewer failed')"}]}
